```cpp
#include <iostream>
#include <vector>
#include <set>
#include <utility>

// Use this structure to store endpoints of a line segment
struct LineSegment {
    int x1, y1;
    int x2, y2;

    LineSegment(int x1, int y1, int x2, int y2) : x1(x1), y1(y1), x2(x2), y2(y2) {}
};

// Check if three lines form a triangle (They should not be collinear)
bool formsTriangle(LineSegment s1, LineSegment s2, LineSegment s3) {
    std::set<int> points;

    if((s1.x1 == s2.x1) && (s1.y1 == s2.y1)) s1.x2 = s2.x2, s1.y2 = s2.y2; // merge if s1 == s2
    points.insert({s1.x1, s1.y1}); points.insert({s1.x2, s1.y2});

    if((s2.x1 == s3.x1) && (s2.y1 == s3.y1)) s2.x2 = s3.x2, s2.y2 = s3.y2;
    points.insert({s2.x1, s2.y1}); points.insert({s2.x2, s2.y2});

    if((s1.x1 == s3.x1) && (s1.y1 == s3.y1)) s3.x2 = s1.x2, s3.y2 = s1.y2;
    points.insert({s3.x1, s3.y1}); points.insert({s3.x2, s3.y2});

    if(points.size() == 3) return true;

    return false;
}

// Function to count triangles
int countTriangles(const std::vector<LineSegment>& segments) {
    int count = 0;

    for(int i=0; i<segments.size(); ++i) {
        for(int j=i+1; j<segments.size(); ++j) {
            for(int k=j+1; k<segments.size(); ++k) {
                if(formsTriangle(segments[i], segments[j], segments[k])) {
                    ++count;
                }
            }
        }
    }

    return count;
}

